#!/usr/bin/env python3
"""
Discard Hold'em bot, v1.

- Hand evaluation: rank-multiset and flush-mask lookup tables built at start-up
  (start-up time is not charged), evaluated in numpy batches.
- Preflop: an offline Monte Carlo table (tools/gen_preflop.py) holding each
  3-card hand's percentile and its equity against random / top 50% / top 25% /
  top 12% ranges.
- Postflop: Monte Carlo equity against the opponent's range. Sampled opponent
  hands are weighted by how well they fit the opponent's actions (preflop
  strength, aggression on each street) and their exposed discard.
- Discard: keep the pair with the highest equity against that range.
- Opponent model: per-situation preflop raise rates, postflop aggression and
  fold-to-bet rates. They widen or narrow ranges and decide bluffs and sizing.
- Match lock: once the lead exceeds the cost of folding every remaining hand,
  fold everything to make the match win certain.
"""

import base64
import json
import math
import os
import random
import sys
import time
from itertools import combinations, permutations

import numpy as np

RANKS = "23456789TJQKA"
SUITS = "shdc"
CARD_INDEX = {r + s: 4 * i + j for i, r in enumerate(RANKS) for j, s in enumerate(SUITS)}
CARD_NAME = {v: k for k, v in CARD_INDEX.items()}
RNG = np.random.default_rng()
LOCK_DISABLED = bool(os.environ.get("BOT_NO_LOCK"))  # local testing only: measure raw chip rates


def log(*args):
    print(*args, file=sys.stderr, flush=True)


# ------------------------------------------------------------- hand evaluator
# A hand value is an int, category << 20 | up to five 4-bit ranks, so larger is
# better. Categories: 0 high card, 1 pair, ..., 4 straight, 5 flush, ..., 8
# straight flush. A card is 4 * rank + suit, rank 0 (deuce) to 12 (ace).

STRAIGHTS = [(0x1F << (h - 4), h) for h in range(12, 3, -1)] + [(0x100F, 3)]


def _straight_high(mask):
    for window, high in STRAIGHTS:
        if (mask & window) == window:
            return high
    return -1


def _enc(cat, ranks):
    value = cat << 20
    for i, r in enumerate(ranks):
        value |= r << (16 - 4 * i)
    return value


def _nonflush_value(cnt):
    """Best non-flush five-card value from a rank-count vector of 5 to 7 cards."""
    desc = [r for r in range(12, -1, -1) if cnt[r]]
    quads = [r for r in desc if cnt[r] == 4]
    trips = [r for r in desc if cnt[r] == 3]
    pairs = [r for r in desc if cnt[r] == 2]
    if quads:
        return _enc(7, [quads[0], next(r for r in desc if r != quads[0])])
    if trips and (len(trips) > 1 or pairs):
        return _enc(6, [trips[0], max(trips[1:] + pairs)])
    high = _straight_high(sum(1 << r for r in desc))
    if high >= 0:
        return _enc(4, [high])
    if trips:
        return _enc(3, [trips[0]] + [r for r in desc if r != trips[0]][:2])
    if len(pairs) >= 2:
        p1, p2 = pairs[:2]
        return _enc(2, [p1, p2] + [r for r in desc if r != p1 and r != p2][:1])
    if pairs:
        return _enc(1, [pairs[0]] + [r for r in desc if r != pairs[0]][:3])
    return _enc(0, desc[:5])


def _build_tables():
    keys, vals = [], []
    cnt = [0] * 13

    def rec(r, total, key):
        if r == 13:
            if total >= 5:
                keys.append(key)
                vals.append(_nonflush_value(cnt))
            return
        for c in range(min(4, 7 - total) + 1):
            cnt[r] = c
            rec(r + 1, total + c, key + c * 5 ** r)
        cnt[r] = 0

    rec(0, 0, 0)
    order = np.argsort(keys)
    nf_keys = np.array(keys, dtype=np.int64)[order]
    nf_vals = np.array(vals, dtype=np.int64)[order]

    flush = np.zeros(8192, dtype=np.int64)    # flush value of a suit's rank mask, 0 if < 5 cards
    sd_outs = np.zeros(8192, dtype=np.int64)  # ranks that would complete a straight
    for m in range(8192):
        high = _straight_high(m)
        if bin(m).count("1") >= 5:
            if high >= 0:
                flush[m] = _enc(8, [high])
            else:
                flush[m] = _enc(5, [r for r in range(12, -1, -1) if m >> r & 1][:5])
        if high < 0:
            outs = 0
            for window, _ in STRAIGHTS:
                miss = window & ~m
                if miss and not miss & (miss - 1):
                    outs |= miss
            sd_outs[m] = bin(outs).count("1")
    return nf_keys, nf_vals, flush, sd_outs


NF_KEYS, NF_VALS, FLUSH, SD_OUTS = _build_tables()
C_POW5 = np.array([5 ** (c >> 2) for c in range(52)], dtype=np.int64)
C_BIT = np.array([1 << (c >> 2) for c in range(52)], dtype=np.int64)
C_SUIT = np.arange(52) & 3
C_SBIT = np.zeros((4, 52), dtype=np.int64)
C_SBIT[C_SUIT, np.arange(52)] = C_BIT


def evaluate(cards):
    """Values of an (N, 5..7) array of cards."""
    best = NF_VALS[np.searchsorted(NF_KEYS, C_POW5[cards].sum(axis=1))]
    for suit in range(4):
        best = np.maximum(best, FLUSH[C_SBIT[suit][cards].sum(axis=1)])
    return best


def keep_score(hole, flop):
    """Heuristic flop strength of keeping `hole` (N, 2) on `flop` (N, 3): made hand plus draws."""
    five = np.concatenate([hole, flop], axis=1)
    v = evaluate(five)
    cat = v >> 20
    score = cat * 169 + ((v >> 16) & 15) * 13 + ((v >> 12) & 15)
    sd = SD_OUTS[np.bitwise_or.reduce(C_BIT[five], axis=1)]
    suits = C_SUIT[five]
    fd = np.zeros(len(v), dtype=bool)
    for suit in range(4):
        fd |= (suits == suit).sum(axis=1) == 4
    bonus = np.where(fd, 220, 0) + np.where(sd >= 2, 150, np.where(sd == 1, 50, 0))
    return score + np.where(cat < 4, bonus, 0)


KEEP_IDX = np.array([[1, 2], [0, 2], [0, 1]])  # row d: the cards kept when discarding card d


def heuristic_keeps(three, flop):
    """For (N, 3) hands on (N, 3) flops: (discard index, score of the kept pair)."""
    scores = np.stack([keep_score(three[:, k], flop) for k in KEEP_IDX], axis=1)
    return scores.argmax(axis=1), scores.max(axis=1)


# ------------------------------------------------------------ preflop table

# BEGIN PREFLOP DATA (generated by tools/gen_preflop.py; do not edit)
PREFLOP_DATA = ""
# END PREFLOP DATA

PRE_COLUMNS = 5  # percentile, equity vs random, vs top 50%, vs top 25%, vs top 12%
PRE_WIDTHS = (1.0, 0.5, 0.25, 0.12)


def _load_preflop():
    lut = np.full((PRE_COLUMNS, 52, 52, 52), 0.5, dtype=np.float32)
    if not PREFLOP_DATA:
        return lut
    raw = np.frombuffer(base64.b64decode(PREFLOP_DATA), dtype=np.uint8)
    raw = raw.reshape(PRE_COLUMNS, -1).astype(np.float32) / 255.0
    combos = np.array(list(combinations(range(52), 3)))
    for p in permutations(range(3)):
        lut[:, combos[:, p[0]], combos[:, p[1]], combos[:, p[2]]] = raw
    return lut


PRE = _load_preflop()


def pre_lookup(hand):
    return [float(x) for x in PRE[:, hand[0], hand[1], hand[2]]]


# ----------------------------------------------------------- Monte Carlo help

def deal(dead, n, k):
    """n rows of k distinct cards not in `dead`."""
    deck = np.array([c for c in range(52) if c not in dead], dtype=np.intp)
    keys = RNG.random((n, deck.size), dtype=np.float32)
    return deck[np.argsort(keys, axis=1)[:, :k]]


def pct_rank(x):
    """Rank of each sample within the batch, scaled to (0, 1)."""
    r = np.empty(x.size)
    r[np.argsort(x, kind="stable")] = np.arange(x.size)
    return (r + 0.5) / x.size


def range_weight(p, a):
    """Weight for samples at percentile p: a > 0 favours strong hands, a < 0 weak ones."""
    if a >= 0:
        return p ** a
    return 1.0 + max(a, -0.6) * p


def showdown(mine, opp):
    return (mine > opp) + 0.5 * (mine == opp)


def wavg(x, w):
    return float((x * w).sum() / max(w.sum(), 1e-12))


# --------------------------------------------------------------- action history

def replay(history, me_button):
    """Annotate each history entry as (street, actor, action, facing, size).

    facing: chips the actor had to call. size: for raises, the raise beyond a
    call as a fraction of the pot after that call.
    """
    total = {"me": 1, "opp": 2} if me_button else {"me": 2, "opp": 1}
    street, bet, out = None, None, []
    for e in history:
        if e.get("street") != street:
            street = e.get("street")
            bet = dict(total) if street == "preflop" else {"me": 0, "opp": 0}
        actor = e.get("actor")
        other = "opp" if actor == "me" else "me"
        action = e.get("action")
        facing = bet[other] - bet[actor]
        size = 0.0
        if action in ("call", "raise"):
            amount = e.get("amount", bet[other])
            if action == "raise":
                size = (amount - bet[other]) / max(1, total["me"] + total["opp"] + facing)
            total[actor] += amount - bet[actor]
            bet[actor] = amount
        out.append((street, actor, action, facing, size))
    return out


def pre_situation(prev):
    """Which preflop spot the opponent faced, given the event before its action."""
    if prev is None:
        return "open"  # opponent is the button, first to act
    if prev[1] == "me" and prev[2] == "call":
        return "vs_limp"
    if prev[1] == "me" and prev[2] == "raise":
        return "vs_raise"
    return None


# --------------------------------------------------------------- opponent model

class OppModel:
    def __init__(self):
        # [hits, trials], seeded with priors
        self.pre_raise = {"open": [3.3, 6.0], "vs_limp": [1.8, 6.0], "vs_raise": [0.9, 6.0]}
        self.pre_fold_vs_raise = [2.0, 6.0]
        self.post_raise = [2.0, 8.0]   # opponent raises per postflop decision
        self.fold_to_bet = [3.2, 8.0]  # opponent folds when facing our postflop bet

    @staticmethod
    def rate(stat):
        return stat[0] / stat[1]

    def update(self, history, me_button):
        prev = None
        for ev in replay(history, me_button):
            street, actor, action, facing, _ = ev
            if actor == "opp":
                if street == "preflop":
                    key = pre_situation(prev)
                    if key:
                        self.pre_raise[key][0] += action == "raise"
                        self.pre_raise[key][1] += 1
                    if key == "vs_raise":
                        self.pre_fold_vs_raise[0] += action == "fold"
                        self.pre_fold_vs_raise[1] += 1
                else:
                    self.post_raise[0] += action == "raise"
                    self.post_raise[1] += 1
                    if prev and prev[0] == street and prev[1] == "me" and prev[2] == "raise":
                        self.fold_to_bet[0] += action == "fold"
                        self.fold_to_bet[1] += 1
            prev = ev

    def tightness(self):
        """Above 1 for opponents who rarely raise postflop (their raises mean more)."""
        return min(1.6, max(0.35, 0.25 / self.rate(self.post_raise)))

    def pre_width(self, events):
        """Fraction of hands the opponent's preflop actions so far represent."""
        width, prev = 1.0, None
        for ev in events:
            if ev[0] != "preflop":
                break
            if ev[1] == "opp" and ev[2] == "raise":
                key = pre_situation(prev) or "vs_raise"
                width *= min(0.95, self.rate(self.pre_raise[key]))
            prev = ev
        return max(width, 0.03)

    def pre_alpha(self, events):
        pre = [ev for ev in events if ev[0] == "preflop" and ev[1] == "opp"]
        if any(ev[2] == "raise" for ev in pre):
            width = self.pre_width(events)
            return min(6.0, (1.0 - width) / width)
        if pre and pre[-1][2] == "call" and pre[-1][3] > 1:
            return 0.5  # called a raise
        return -0.3     # limped or checked: the strongest hands would have raised

    def street_alpha(self, events, street):
        a, tight = 0.0, self.tightness()
        for s, actor, action, facing, size in events:
            if s != street or actor != "opp":
                continue
            if action == "raise":
                a += tight * (0.8 + 0.6 * min(size, 1.5))
            elif action == "call":
                a += 0.5 * tight
            elif action == "check":
                a -= 0.3
        return a


# ------------------------------------------------------------------------ bot

class Bot:
    def __init__(self):
        self.total_hands = 400
        self.hand_id = 0
        self.net = 0
        self.net_sq = 0.0
        self.opp = OppModel()
        self.ms_per_sample = {"flop": 0.004, "later": 0.004}
        self.button = False
        self.locked = False
        self.hole = []
        self.flop = []
        self.my_discard = None
        self.opp_discard = None
        self._warm_up()

    def _warm_up(self):
        """Run each simulation once so the first timed request is not the slowest."""
        hand = [CARD_INDEX[c] for c in ("As", "Kd", "7c")]
        flop = [CARD_INDEX[c] for c in ("Ah", "7d", "2s")]
        events = []
        t = time.perf_counter()
        self.flop_equities(hand, flop, events, 1000)
        self.ms_per_sample["flop"] = (time.perf_counter() - t) * 1000 / 1000
        t = time.perf_counter()
        self.later_equity(hand[:2], flop + [CARD_INDEX["3c"]], hand[2], CARD_INDEX["Qs"], events, 1000)
        self.ms_per_sample["later"] = (time.perf_counter() - t) * 1000 / 1000

    # ---- bookkeeping

    def on_message(self, msg):
        t = msg.get("type")
        if t == "init":
            self.total_hands = int(msg.get("total_hands", self.total_hands))
        elif t == "new_hand":
            self.hand_id = int(msg.get("hand_id", self.hand_id + 1))
            self.button = msg.get("seat") == "button"
            self.hole = [CARD_INDEX[c] for c in msg.get("hole_cards", [])]
            self.flop, self.my_discard, self.opp_discard = [], None, None
            self._history = None
            self.locked = self._lead_is_safe()
        elif t == "discard_result":
            self.my_discard = CARD_INDEX.get(msg.get("my_discard"))
            self.opp_discard = CARD_INDEX.get(msg.get("opp_discard"))
            self.hole = [CARD_INDEX[c] for c in msg.get("hole_cards", [])]
        elif t == "hand_result":
            self.net += int(msg.get("net", 0))
            self.net_sq += float(msg.get("net", 0)) ** 2
            self.opp.update(msg.get("history") or [], self.button)
            if self.hand_id % 100 == 0:
                o = self.opp
                log(f"hand {self.hand_id} net {self.net:+d} | open {o.rate(o.pre_raise['open']):.2f} "
                    f"3bet {o.rate(o.pre_raise['vs_raise']):.2f} post_raise {o.rate(o.post_raise):.2f} "
                    f"fold_to_bet {o.rate(o.fold_to_bet):.2f}")

    def _lead_is_safe(self):
        """Fold out the match? Only if folding every remaining hand still wins, and either
        the capped tie-break score is already maxed or playing on risks the win."""
        if LOCK_DISABLED:
            return False
        remaining = self.total_hands - self.hand_id + 1
        as_button = (remaining + 1) // 2 if self.button else remaining // 2
        cost = as_button * 1 + (remaining - as_button) * 2
        if self.net <= cost + 2:
            return False
        cap = 1000 if self.total_hands > 500 else 400
        if self.net - cost >= cap:  # the capped tie-break score is already maxed
            return True
        played = max(1, self.hand_id - 1)
        sd = max(25.0, math.sqrt(self.net_sq / played)) * math.sqrt(remaining)
        drift = 0.5 * self.net / played * remaining
        p_lose = 0.5 * math.erfc((self.net + drift) / sd / math.sqrt(2))
        return p_lose > 0.01

    def n_samples(self, req, kind, calls_per_hand=4.0):
        left = float(req.get("time_left_ms", 60000))
        if left < 2000:
            return 100
        hands_left = max(1, self.total_hands - self.hand_id + 1)
        budget_ms = 0.3 * left / hands_left / calls_per_hand
        return int(max(150, min(5000, budget_ms / max(self.ms_per_sample[kind], 1e-4))))

    def _timed(self, kind, n, fn, *args):
        t = time.perf_counter()
        out = fn(*args, n)
        per = (time.perf_counter() - t) * 1000 / n
        self.ms_per_sample[kind] = 0.8 * self.ms_per_sample[kind] + 0.2 * per
        return out

    # ---- simulations

    def flop_equities(self, my3, flop, events, n):
        """Equity of each of our three discards (index = card discarded) vs the opponent's range.

        Returns (equities, strong_equities); the latter is against the part of the
        range that would continue against a bet.
        """
        s = deal(set(my3) | set(flop), n, 5)
        opp3, runout = s[:, :3], s[:, 3:]
        flop_n = np.broadcast_to(np.array(flop), (n, 3))
        disc, opp_score = heuristic_keeps(opp3, flop_n)
        opp_keep = np.take_along_axis(opp3, KEEP_IDX[disc], axis=1)
        board = np.concatenate([flop_n, runout], axis=1)
        opp_val = evaluate(np.concatenate([opp_keep, board], axis=1))

        strength = pct_rank(opp_score)
        w = range_weight(PRE[0][opp3[:, 0], opp3[:, 1], opp3[:, 2]], self.opp.pre_alpha(events))
        w = w * range_weight(strength, self.opp.street_alpha(events, "flop"))
        w_strong = w * strength ** 1.2

        my3 = np.array(my3)
        eqs, strong = [], []
        for k in KEEP_IDX:
            mine = np.broadcast_to(my3[k], (n, 2))
            res = showdown(evaluate(np.concatenate([mine, board], axis=1)), opp_val)
            eqs.append(wavg(res, w))
            strong.append(wavg(res, w_strong))
        return eqs, strong

    def later_equity(self, my2, board, my_disc, opp_disc, events, n):
        """Turn or river equity vs the opponent's 2-card range. Returns (equity, strong_equity)."""
        dead = set(my2) | set(board) | {my_disc, opp_disc}
        s = deal(dead, n, 2 + 5 - len(board))
        opp2 = s[:, :2]
        board_n = np.broadcast_to(np.array(board), (n, len(board)))
        full_board = np.concatenate([board_n, s[:, 2:]], axis=1)
        flop_n = board_n[:, :3]
        od = np.full((n, 1), opp_disc)

        # The opponent's original three cards, and whether its exposed discard fits them.
        w = range_weight(PRE[0][opp2[:, 0], opp2[:, 1], od[:, 0]], self.opp.pre_alpha(events))
        kept = keep_score(opp2, flop_n)
        alt = np.maximum(keep_score(np.concatenate([opp2[:, :1], od], axis=1), flop_n),
                         keep_score(np.concatenate([opp2[:, 1:], od], axis=1), flop_n))
        w = w * np.where(kept >= alt, 1.0, 0.35)
        w = w * range_weight(pct_rank(kept), self.opp.street_alpha(events, "flop"))

        if len(board) == 5:
            turn_val = evaluate(np.concatenate([opp2, board_n[:, :4]], axis=1))
            w = w * range_weight(pct_rank(turn_val), self.opp.street_alpha(events, "turn"))
        street = "turn" if len(board) == 4 else "river"
        now = pct_rank(evaluate(np.concatenate([opp2, board_n], axis=1)))
        w = w * range_weight(now, self.opp.street_alpha(events, street))

        mine = np.broadcast_to(np.array(my2), (n, 2))
        res = showdown(evaluate(np.concatenate([mine, full_board], axis=1)),
                       evaluate(np.concatenate([opp2, full_board], axis=1)))
        return wavg(res, w), wavg(res, w * now ** 1.2)

    # ---- decisions

    @staticmethod
    def _act(action, amount=None):
        msg = {"type": "action", "action": action}
        if amount is not None:
            msg["amount"] = int(amount)
        return msg

    def _raise_to(self, req, amount):
        lo, hi = req["min_raise"], req["max_raise"]
        amount = int(round(max(lo, min(hi, amount))))
        if amount > 0.6 * hi:  # leaving a sliver behind is pointless: shove
            amount = hi
        return self._act("raise", amount)

    def _pot_raise(self, req, frac):
        return self._raise_to(req, req["opp_bet"] + frac * (req["pot"] + req["to_call"]))

    def _passive(self, req):
        return self._act("check" if "check" in req["legal_actions"] else "fold")

    def action(self, req):
        if self.locked:
            return self._passive(req)
        events = replay(req.get("history") or [], self.button)
        street = req["street"]
        if street == "preflop":
            return self.preflop(req, events)
        board = [CARD_INDEX[c] for c in req["board"]]
        if street == "flop":
            n = self.n_samples(req, "flop")
            eqs, strong = self._timed("flop", n, self.flop_equities, self.hole, board, events)
            best = int(np.argmax(eqs))
            return self.postflop(req, street, eqs[best], strong[best])
        n = self.n_samples(req, "later")
        e, e_strong = self._timed("later", n, self.later_equity, self.hole, board,
                                  self.my_discard, self.opp_discard, events)
        return self.postflop(req, street, e, e_strong)

    def preflop(self, req, events):
        pct, *eq_cols = pre_lookup(self.hole)
        legal, to_call, pot = req["legal_actions"], req["to_call"], req["pot"]
        can_raise = "raise" in legal

        if to_call == 0:  # big blind after a limp
            if can_raise and pct >= 0.70:
                return self._raise_to(req, random.choice((6, 7, 8)))
            return self._act("check")

        if not events:  # button, first to act
            if can_raise and pct >= 0.40:
                return self._raise_to(req, 6)
            return self._act("call" if pct >= 0.10 else "fold")

        # Facing a raise: equity against the range the opponent's raises represent.
        width = self.opp.pre_width(events)
        logw = np.log(np.array(PRE_WIDTHS))
        eq = float(np.interp(np.log(width), logw[::-1], np.array(eq_cols)[::-1]))
        my_raises = sum(1 for ev in events if ev[1] == "me" and ev[2] == "raise")
        pot_odds = to_call / (pot + to_call)
        big = to_call >= 0.4 * req["my_stack"]
        if can_raise and eq >= 0.58 + 0.04 * my_raises:
            return self._raise_to(req, 3 * req["opp_bet"])
        if eq * (1.0 if big else 0.9) >= pot_odds:
            return self._act("call")
        return self._act("fold")

    def postflop(self, req, street, e, e_strong):
        legal, to_call, pot = req["legal_actions"], req["to_call"], req["pot"]
        can_raise = "raise" in legal
        fold_rate = self.opp.rate(self.opp.fold_to_bet)
        station = fold_rate < 0.25

        if to_call > 0:
            pot_odds = to_call / (pot + to_call)
            committed = to_call >= 0.5 * req["my_stack"]
            margin = 0.0 if street == "river" or committed else 0.03
            raise_t = {"flop": 0.78, "turn": 0.80, "river": 0.85}[street]
            if can_raise and e >= raise_t:
                return self._pot_raise(req, 0.8)
            if e >= pot_odds + margin:
                return self._act("call")
            return self._act("fold")

        value_t = {"flop": 0.55, "turn": 0.53, "river": 0.52}[street] - (0.03 if station else 0.0)
        if can_raise and e_strong >= value_t:
            frac = 0.5 if e_strong < 0.62 else 0.75 if e_strong < 0.75 else 1.0
            return self._pot_raise(req, frac + (0.25 if station else 0.0))
        if can_raise and not station and e < 0.4 and random.random() < min(0.4, fold_rate - 0.3):
            return self._pot_raise(req, 0.66)
        return self._act("check")

    def discard(self, req):
        hole = [CARD_INDEX[c] for c in req["hole_cards"]]
        board = [CARD_INDEX[c] for c in req["board"]][:3]
        self.hole, self.flop = hole, board
        events = replay(self._history or [], self.button)
        n = self.n_samples(req, "flop")
        eqs, _ = self._timed("flop", n, self.flop_equities, hole, board, events)
        return {"type": "discard", "card": CARD_NAME[hole[int(np.argmax(eqs))]]}

    _history = None

    def handle(self, msg):
        """Reply to a request; None for informational messages."""
        t = msg.get("type")
        if t == "action_request":
            self._history = msg.get("history")
            try:
                return self.action(msg)
            except Exception as exc:  # never forfeit over a bug
                log(f"action error: {exc!r}")
                return self._passive(msg)
        if t == "discard_request":
            try:
                return self.discard(msg)
            except Exception as exc:
                log(f"discard error: {exc!r}")
                cards = msg.get("hole_cards") or ["2s"]
                return {"type": "discard", "card": min(cards, key=lambda c: RANKS.index(c[0]))}
        try:
            self.on_message(msg)
        except Exception as exc:
            log(f"message error: {exc!r}")
        return None


def main():
    bot = Bot()
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            msg = json.loads(line)
        except ValueError:
            continue
        if not isinstance(msg, dict):
            continue
        if msg.get("type") == "match_end":
            break
        reply = bot.handle(msg)
        if reply is not None:
            print(json.dumps(reply), flush=True)


if __name__ == "__main__":
    main()
